def decide(view):
    # Diagnosis: The incumbent policy repeatedly expands the root node despite having discovered high-quality leaves.
    # This is inefficient because the root score is null and expanding it just starts a new attempt rather than refining
    # the best-known path. The policy should prioritize expanding the leaf with the best score to find better refinements.
    # Also, we should avoid expanding nodes with very low scores (e.g., -4.0) if we have better options.
    # We will sort the frontier by score (descending, handling null scores) and pick the best candidate.
    # Fixed non-finite number error by replacing float('-inf') with a sufficiently small finite value (-1e9).

    frontier = view['frontier']

    if not frontier:
        return {'expand': [], 'stop': True}

    # Sort frontier by score descending. Null scores (root) should be treated as very low priority.
    # We use a helper to handle null scores for sorting.
    def score_key(node):
        s = node.get('score')
        if s is None:
            return -1e9
        return s

    # Sort and get the top candidates. We can pick up to 3 to balance exploration, 
    # but prioritizing the single best leaf minimizes wasted probes per round.
    sorted_frontier = sorted(frontier, key=score_key, reverse=True)

    # Select top 1 candidate to minimize probe cost while maximizing score improvement.
    candidates = sorted_frontier[:1]

    if not candidates:
        return {'expand': [], 'stop': True}

    # Return the expansion of the top candidate.
    return {'expand': [c['id'] for c in candidates], 'stop': False}
